def _ext_from_magic(data):
    """从文件头推断扩展名（title 无扩展名时兜底）。"""
    if data[:3] == b"\xff\xd8\xff":
        return ".jpg"
    if data[:4] == b"\x89PNG":
        return ".png"
    b = data[:6]
    if b in (b"GIF87a", b"GIF89a") or data[:4] == b"GIF8":
        return ".gif"
    if data[:2] == b"BM":
        return ".bmp"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return ".webp"
    if data[:4] == b"PK\x03\x04":
        return ".zip"
    if data[:4] == b"%PDF":
        return ".pdf"
    return ""

